using System;using System.Collections.Generic;using System.Linq;using System.Runtime.CompilerServices;using System.Text;using System.Threading.Tasks;namespace CSharpPractice.main.string_operation{    public class CountVowels    {        public static void CountVowelsMethod()        {            char[] vowels = { 'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U' };            var exit = "exit";            while (true)            {                Console.WriteLine("Enter a word to count vowels");                var word = Console.ReadLine();                var vowelsCount = 0;                if (string.IsNullOrWhiteSpace(word) || int.TryParse(word, out _) || string.Equals(word, exit, StringComparison.OrdinalIgnoreCase))                {                    break;                }                for (int i = 0; i < word.Length; i++)                {                    var c = word[i];                    if (vowels.Contains(c))                        vowelsCount++;                }                Console.WriteLine("vowels count: " + vowelsCount);            }        }    }}